import{_ as n,H as e,f as s,i as t}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"11 | Java线程（下）：为什么局部变量是线程安全的？","description":"","frontmatter":{},"headers":[{"level":2,"title":"方法是如何被执行的","slug":"方法是如何被执行的","link":"#方法是如何被执行的","children":[]},{"level":2,"title":"局部变量存哪里？","slug":"局部变量存哪里","link":"#局部变量存哪里","children":[]},{"level":2,"title":"调用栈与线程","slug":"调用栈与线程","link":"#调用栈与线程","children":[]},{"level":2,"title":"线程封闭","slug":"线程封闭","link":"#线程封闭","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"课后思考","slug":"课后思考","link":"#课后思考","children":[]}],"relativePath":"Java并发编程实战/11-Java线程（下）：为什么局部变量是线程安全的？.md","filePath":"Java并发编程实战/11-Java线程（下）：为什么局部变量是线程安全的？.md","lastUpdated":1779815850000}'),i={name:"Java并发编程实战/11-Java线程（下）：为什么局部变量是线程安全的？.md"};function p(c,a,l,o,r,h){return e(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="_11-java线程-下-为什么局部变量是线程安全的" tabindex="-1">11 | Java线程（下）：为什么局部变量是线程安全的？ <a class="header-anchor" href="#_11-java线程-下-为什么局部变量是线程安全的" aria-label="Permalink to &quot;11 | Java线程（下）：为什么局部变量是线程安全的？&quot;">​</a></h1><p>我们一遍一遍重复再重复地讲到，多个线程同时访问共享变量的时候，会导致并发问题。那在Java语言里，是不是所有变量都是共享变量呢？工作中我发现不少同学会给方法里面的局部变量设置同步，显然这些同学并没有把共享变量搞清楚。那Java方法里面的局部变量是否存在并发问题呢？下面我们就先结合一个例子剖析下这个问题。</p><p>比如，下面代码里的 fibonacci() 这个方法，会根据传入的参数 n ，返回 1 到 n 的斐波那契数列，斐波那契数列类似这样： 1、1、2、3、5、8、13、21、34……第1项和第2项是1，从第3项开始，每一项都等于前两项之和。在这个方法里面，有个局部变量：数组 r 用来保存数列的结果，每次计算完一项，都会更新数组 r 对应位置中的值。你可以思考这样一个问题，当多个线程调用 fibonacci() 这个方法的时候，数组 r 是否存在数据竞争（Data Race）呢？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 返回斐波那契数列</span></span>
<span class="line"><span>int[] fibonacci(int n) {</span></span>
<span class="line"><span>  // 创建结果数组</span></span>
<span class="line"><span>  int[] r = new int[n];</span></span>
<span class="line"><span>  // 初始化第一、第二个数</span></span>
<span class="line"><span>  r[0] = r[1] = 1;  // ①</span></span>
<span class="line"><span>  // 计算2..n</span></span>
<span class="line"><span>  for(int i = 2; i &amp;lt; n; i++) {</span></span>
<span class="line"><span>      r[i] = r[i-2] + r[i-1];</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  return r;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>你自己可以在大脑里模拟一下多个线程调用 fibonacci() 方法的情景，假设多个线程执行到 ① 处，多个线程都要对数组r的第1项和第2项赋值，这里看上去感觉是存在数据竞争的，不过感觉再次欺骗了你。</p><p>其实很多人也是知道局部变量不存在数据竞争的，但是至于原因嘛，就说不清楚了。</p><p>那它背后的原因到底是怎样的呢？要弄清楚这个，你需要一点编译原理的知识。你知道在CPU层面，是没有方法概念的，CPU的眼里，只有一条条的指令。编译程序，负责把高级语言里的方法转换成一条条的指令。所以你可以站在编译器实现者的角度来思考“怎么完成方法到指令的转换”。</p><h2 id="方法是如何被执行的" tabindex="-1">方法是如何被执行的 <a class="header-anchor" href="#方法是如何被执行的" aria-label="Permalink to &quot;方法是如何被执行的&quot;">​</a></h2><p>高级语言里的普通语句，例如上面的 <code>r[i] = r[i-2] + r[i-1];</code> 翻译成CPU的指令相对简单，可方法的调用就比较复杂了。例如下面这三行代码：第1行，声明一个int变量a；第2行，调用方法 fibonacci(a)；第3行，将b赋值给c。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int a = 7；</span></span>
<span class="line"><span>int[] b = fibonacci(a);</span></span>
<span class="line"><span>int[] c = b;</span></span></code></pre></div><p>当你调用fibonacci(a)的时候，CPU要先找到方法 fibonacci() 的地址，然后跳转到这个地址去执行代码，最后CPU执行完方法 fibonacci() 之后，要能够返回。首先找到调用方法的下一条语句的地址：也就是 <code>int[] c=b;</code> 的地址，再跳转到这个地址去执行。 你可以参考下面这个图再加深一下理解。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/86695/9bd881b545e1c67142486f6594dc9d1f.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/86695/9bd881b545e1c67142486f6594dc9d1f.png" alt=""></a></p><p>方法的调用过程</p><p>到这里，方法调用的过程想必你已经清楚了，但是还有一个很重要的问题，“CPU去哪里找到调用方法的参数和返回地址？”如果你熟悉CPU的工作原理，你应该会立刻想到： <strong>通过CPU的堆栈寄存器</strong>。CPU支持一种栈结构，栈你一定很熟悉了，就像手枪的弹夹，先入后出。因为这个栈是和方法调用相关的，因此经常被称为 <strong>调用栈</strong>。</p><p>例如，有三个方法A、B、C，他们的调用关系是A-&gt;B-&gt;C（A调用B，B调用C），在运行时，会构建出下面这样的调用栈。每个方法在调用栈里都有自己的独立空间，称为 <strong>栈帧</strong>，每个栈帧里都有对应方法需要的参数和返回地址。当调用方法时，会创建新的栈帧，并压入调用栈；当方法返回时，对应的栈帧就会被自动弹出。也就是说， <strong>栈帧和方法是同生共死的</strong>。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/86695/674bb47feccbf55cf0b6acc5c92e4fc7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/86695/674bb47feccbf55cf0b6acc5c92e4fc7.png" alt=""></a></p><p>调用栈结构</p><p>利用栈结构来支持方法调用这个方案非常普遍，以至于CPU里内置了栈寄存器。虽然各家编程语言定义的方法千奇百怪，但是方法的内部执行原理却是出奇的一致：都是 <strong>靠栈结构解决</strong> 的。Java语言虽然是靠虚拟机解释执行的，但是方法的调用也是利用栈结构解决的。</p><h2 id="局部变量存哪里" tabindex="-1">局部变量存哪里？ <a class="header-anchor" href="#局部变量存哪里" aria-label="Permalink to &quot;局部变量存哪里？&quot;">​</a></h2><p>我们已经知道了方法间的调用在CPU眼里是怎么执行的，但还有一个关键问题：方法内的局部变量存哪里？</p><p>局部变量的作用域是方法内部，也就是说当方法执行完，局部变量就没用了，局部变量应该和方法同生共死。此时你应该会想到调用栈的栈帧，调用栈的栈帧就是和方法同生共死的，所以局部变量放到调用栈里那儿是相当的合理。事实上，的确是这样的， <strong>局部变量就是放到了调用栈里</strong>。于是调用栈的结构就变成了下图这样。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/86695/ece8c32d23e4777c370f594c97762a9c.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/86695/ece8c32d23e4777c370f594c97762a9c.png" alt=""></a></p><p>保护局部变量的调用栈结构</p><p>这个结论相信很多人都知道，因为学Java语言的时候，基本所有的教材都会告诉你 new 出来的对象是在堆里，局部变量是在栈里，只不过很多人并不清楚堆和栈的区别，以及为什么要区分堆和栈。现在你应该很清楚了，局部变量是和方法同生共死的，一个变量如果想跨越方法的边界，就必须创建在堆里。</p><h2 id="调用栈与线程" tabindex="-1">调用栈与线程 <a class="header-anchor" href="#调用栈与线程" aria-label="Permalink to &quot;调用栈与线程&quot;">​</a></h2><p>两个线程可以同时用不同的参数调用相同的方法，那调用栈和线程之间是什么关系呢？答案是： <strong>每个线程都有自己独立的调用栈</strong>。因为如果不是这样，那两个线程就互相干扰了。如下面这幅图所示，线程A、B、C每个线程都有自己独立的调用栈。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/86695/840cb955e521bd51776dbcdad3dba11a.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98/images/86695/840cb955e521bd51776dbcdad3dba11a.png" alt=""></a></p><p>线程与调用栈的关系图</p><p>现在，让我们回过头来再看篇首的问题：Java方法里面的局部变量是否存在并发问题？现在你应该很清楚了，一点问题都没有。因为每个线程都有自己的调用栈，局部变量保存在线程各自的调用栈里面，不会共享，所以自然也就没有并发问题。再次重申一遍：没有共享，就没有伤害。</p><h2 id="线程封闭" tabindex="-1">线程封闭 <a class="header-anchor" href="#线程封闭" aria-label="Permalink to &quot;线程封闭&quot;">​</a></h2><p>方法里的局部变量，因为不会和其他线程共享，所以没有并发问题，这个思路很好，已经成为解决并发问题的一个重要技术，同时还有个响当当的名字叫做 <strong>线程封闭</strong>，比较官方的解释是： <strong>仅在单线程内访问数据</strong>。由于不存在共享，所以即便不同步也不会有并发问题，性能杠杠的。</p><p>采用线程封闭技术的案例非常多，例如从数据库连接池里获取的连接Connection，在JDBC规范里并没有要求这个Connection必须是线程安全的。数据库连接池通过线程封闭技术，保证一个Connection一旦被一个线程获取之后，在这个线程关闭Connection之前的这段时间里，不会再分配给其他线程，从而保证了Connection不会有并发问题。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>调用栈是一个通用的计算机概念，所有的编程语言都会涉及到，Java调用栈相关的知识，我并没有花费很大的力气去深究，但是靠着那点C语言的知识，稍微思考一下，基本上也就推断出来了。工作了十几年，我发现最近几年和前些年最大的区别是：很多技术的实现原理我都是靠推断，然后看源码验证，而不是像以前一样纯粹靠看源码来总结了。</p><p>建议你也多研究原理性的东西、通用的东西，有这些东西之后再学具体的技术就快多了。</p><h2 id="课后思考" tabindex="-1">课后思考 <a class="header-anchor" href="#课后思考" aria-label="Permalink to &quot;课后思考&quot;">​</a></h2><p>常听人说，递归调用太深，可能导致栈溢出。你思考一下原因是什么？有哪些解决方案呢？</p><p>欢迎在留言区与我分享你的想法，也欢迎你在留言区记录你的思考过程。感谢阅读，如果你觉得这篇文章对你有帮助的话，也欢迎把它分享给更多的朋友。</p>`,38)])])}const d=n(i,[["render",p]]);export{g as __pageData,d as default};
